-- ═══════════════════════════════════════════════════════════════════════════════════════════════
-- 0076 — A HARBOUR IS REACHED FROM ITS ROADS
--        The roadstead becomes a place: measured, seeded, served — and the course ends there.
-- ═══════════════════════════════════════════════════════════════════════════════════════════════
--
-- GENERATED by scripts/build-sea-migration.mjs — do not hand-edit. Change the sea (scripts/
-- sea-grid.mjs) or the ports and cut a NEW migration; an applied one is history.
--
-- ── THE OWNER, VERBATIM (docs/OWNER_REQUESTS.md:131, row 72) ───────────────────────────────────
--   "create a perpendicular helper line (dotted) that is the shortest point between the land
--    city and nearby shore - sea. Then create a point there, and when the ship arrive at that
--    point, consider it as the ship have landed on land"
--
-- ── WHAT SAYS THE OPPOSITE, NAMED ──────────────────────────────────────────────────────────────
--   * cmd.do_sail takes the port's RAW COORDINATE as the course endpoint (0047:589-590, 0047:602)
--     and grants `snap_nm + 25` nm of land-crossing allowance at each end (0047:588, 0047:606).
--   * voyage.path_refusal skips every sample inside that allowance; the client's mirror of the
--     same rule is src/lib/sea/pathfind.ts:317.
--   * public.sea_reaches records the snap DISTANCE and throws the point away (0046:79), and
--     voyage.water_snap_nm computes the winning cell (0047:225-228) and returns only the number.
--     No function in the chain could answer "WHERE is the water nearest this place".
--   * scripts/sea-grid.mjs:246 `snapToWater` is a THIRD, DIFFERENT snap rule — 8 rings, the
--     first water cell in scan order rather than the nearest — with exactly one build-time
--     caller (scripts/build-sea-places.mjs:157, through findSeaRoute). It is NAMED here rather
--     than fixed: folding it regenerates data/sea-places.json, which is its own slice.
--
-- ── WHAT THIS DOES ─────────────────────────────────────────────────────────────────────────────
--   1. public.sea_reaches gains roadstead_lat/roadstead_lon (numeric(6,3)/(7,3), NOT NULL).
--   2. voyage.water_snap_nm's BODY MOVES DOWN into voyage.water_roadstead(lat, lon), which
--      returns (nm, lat, lon); water_snap_nm keeps its signature and becomes one line over it.
--      One body now answers "where is the water nearest this point, and how far" — which is
--      what makes the JS-generated column checkable against the SQL rule for all 238 rows.
--   3. public.sea_reaches is replaced WHOLE: snap_nm, the two roadstead columns, and `reaches`
--      re-measured ROADSTEAD → ROADSTEAD (the 0052:92-94 delete-and-insert, exactly).
--   4. cmd.do_sail: four hunks. A port end is the ROADSTEAD and its allowance is a flat 25 nm.
--   5. voyage.assert_paths_water: one hunk, the same allowance — with pre-0076 voyages
--      GRANDFATHERED on voyages.departed_at, so a passage a player already bought is judged by
--      the rule it was admitted under.
--   6. world.snapshot().ports[] gains one key, `roadstead` — { lat, lon, nm } — so the chart
--      draws the helper line off a SERVED number and never computes a snap of its own.
--
-- ── WHAT IT SUPERSEDES, AND WHY ────────────────────────────────────────────────────────────────
--   voyage.water_snap_nm(numeric, numeric), created at 0047:199. This file SUPERSEDES it, and
--   the supersede is a fold, not a change of rule: the body is moved down into
--   voyage.water_roadstead(lat, lon) UNCHANGED but for keeping the point it already computed
--   and threw away (0047:225-228), and water_snap_nm becomes one line over it. The SIGNATURE
--   does not move, no function is dropped, and its three existing callers (0047:594, 0047:612,
--   0047:1186-1189) are untouched and read the same numbers as before — so the supersede is a
--   no-op for every caller that existed before this file. What it buys is one body answering
--   "where is the water nearest this point, and how far", which is what lets self-assert (e)
--   re-ask PostgreSQL the question the Node generator answered, for every row.
--   cmd.do_sail, voyage.assert_paths_water and world.snapshot() are RE-CUT, not superseded:
--   each is sliced hunk-by-hunk out of its DEPLOYED body through pg_get_functiondef, so the
--   rest of every one of those bodies is carried across byte-identical.
--
-- ── AND WHAT IT DELIBERATELY DOES NOT ──────────────────────────────────────────────────────────
--   * It does not touch voyage.settle. Arrival is ALREADY right: 0027:409-416 docks her at
--     v.dest_port_id at the ETA, so the moment the course ENDS at the roadstead the owner's
--     sentence is true by the mechanism shipping since 0007. A geometric arrival test would be
--     a second authority for "has she arrived" beside the ETA, and none is written.
--   * It does not shrink the ~21 nm (client) / 25 nm (server) sampling slack every course end
--     still enjoys. src/lib/sea/pathfind.ts:330 gives every path end `cellDiagNm` =
--     0.25 * 60 * sqrt(2) = 21.21 nm unconditionally; a server allowance under that would
--     refuse courses the client's own straightener legitimately produced. Said plainly rather
--     than implied: shrinking THAT is the never-touch-land slice, not this one.
--   * It opens and closes no CHANNEL, moves no price knob, and touches no player row.
--   * IT DOES NOT MOVE THE WATER. The grid built by this run is BYTE-IDENTICAL to the one
--     public.sea_raster already holds (545,989 water cells, 259200 packed bytes, +0 opened,
--     -0 closed), so the raster row is not rewritten. Only what the table SAYS about that
--     water changes.
--
-- ── EVIDENCE, MEASURED BY THIS RUN AGAINST THE APPLIED CHAIN ───────────────────────────────────
--   THE ROADSTEADS. 238 places; 77 already stand on sailable water and are their own
--   roadstead at 0 nm; 161 carry a real roadstead off the quay. Over 10 nm: 139. Over
--   20 nm: 40. Over 30 nm: 13. Over 50 nm: 3. Worst:
--     LNG 67.68 · HAN 58.68 · KHA 57.77 · TOK 47.69 · PAT 47.21 · TRO 45.98 · IZM 40.29 · AMS 35.47
--   235 distinct cells for 238 places — roadsteads are NOT unique and nothing may assume it.
--
--   THE DISTANCE EFFECT, all 28,203 pairs, this table against the one the chain serves:
--     mean -10.89 nm · median -10.94 nm · MEDIAN -0.15 % · 75.8 % of pairs move under 0.5 %
--     1.78 % of pairs move over 5 %. This is NOT a repricing: 0048 moved PRICES; this moves
--     DISTANCES by a fifth of a percent at the median. Every price knob is untouched.
--
--   THE ONLY 5 PAIRS THAT MOVE MORE THAN 500 nm — and every one of them is the documented
--   live breach of the never-touch-land law, repaired:
--     Panama City → Portobelo                 35.5 →    10731.1 nm
--     Panama City → Veracruz                1449.3 →    11746.4 nm
--     Panama City → Port Royal               560.9 →    10577.6 nm
--     Panama City → St. Augustine           1944.6 →    11068.2 nm
--     Hamburg → Lubeck                        31.2 →      577.1 nm
--   Those passages become the long way round. That is the repair, and it is a VISIBLE gameplay
--   change: a house running a Panama-to-Caribbean loop loses a route that was a Panama Canal
--   three and a half centuries early.
--
--   THE LAND GUARD AT ITS OWN SAMPLING, asked of voyage.path_refusal on the applied chain:
--     Panama City → Port Royal       quay→quay 560.9 nm under 10.82+25 / 19.02+25 nm: ACCEPTED
--                                    roads→roads under 25 / 25 nm: E_LAND: the course touches land near 9.35°, -79.24° (segment 0)
--     Hamburg → Lubeck               quay→quay 31.2 nm under 6.33+25 / 21.68+25 nm: ACCEPTED
--                                    roads→roads under 25 / 25 nm: E_LAND: the course touches land near 53.88°, 10.50° (segment 0)
--     The Hamburg row is the worst of the two: the WHOLE 31.2 nm line lies inside
--     head + tail = 78.0 nm, so voyage.path_refusal walks it and checks ZERO samples. The
--     guard is not lenient there — it is switched off.
--
--   PRECISION. Every roadstead is a cell centre (`90 - (row+0.5)*0.25`) or a 2-dp port
--   coordinate, so 3 decimal places is EXACT and lossless — asserted at generation, not hoped.
--   A fourth decimal would be a fiction about a 0.25° raster.
--
-- Depends on: 0002 (ports, seas, gc_distance_nm), 0040 (sea_cells, voyage.sea_at), 0046 (the two
-- tables, voyage.path_nm, voyage.path_refusal), 0047 (cmd.do_sail, voyage.water_snap_nm,
-- voyage.assert_paths_water), 0050 (cmd.do_sail's live body), 0032/0036/0067/0071 (world.snapshot's
-- live body), and the port rows of 0003/0036/0041.
-- ═══════════════════════════════════════════════════════════════════════════════════════════════

-- ── THE SLICER. 0075's helper (0075:66-88) verbatim, with this file's slice id. Its law: a 
-- hunk that does not occur EXACTLY ONCE in the deployed body is a failed apply, so a drifted
-- production body refuses the migration instead of silently taking half of it.
create or replace function pg_temp.recut(p_fn regprocedure, p_drop boolean, variadic p_edits text[])
returns void
language plpgsql
as $recut$
declare
  v_def text := pg_get_functiondef(p_fn);
  v_i   int := 1;
  v_n   int;
begin
  while v_i < array_length(p_edits, 1) loop
    v_n := (length(v_def) - length(replace(v_def, p_edits[v_i], ''))) / length(p_edits[v_i]);
    if v_n <> 1 then
      raise exception '0076 slice: hunk % of % occurs % time(s) in %, expected exactly 1 — the deployed body is not what this migration was generated against.',
        (v_i + 1) / 2, (array_length(p_edits, 1)) / 2, v_n, p_fn;
    end if;
    v_def := replace(v_def, p_edits[v_i], p_edits[v_i + 1]);
    v_i := v_i + 2;
  end loop;
  if p_drop then
    execute format('drop function %s', p_fn::text);
  end if;
  execute v_def;
end $recut$;

-- PRE-IMAGES. "Nothing else moved" is a comparison, never a sentence (NO_SPAGHETTI §3.3).
create temporary table defs_before_0076 as
  select f.fn, pg_get_functiondef(f.fn::regprocedure) as def,
         (select p.proacl::text from pg_proc p where p.oid = f.fn::regprocedure) as acl
    from (values ('cmd.do_sail(uuid, jsonb)'), ('world.snapshot()'),
                 ('voyage.assert_paths_water()')) as f(fn);

-- ── 1. THE COLUMNS ─────────────────────────────────────────────────────────────────────────────
-- On sea_reaches and NOT on public.ports, deliberately: `ports` is the AUTHORED world
-- (data/ports.json -> 0003/0041/0058) and scripts/db/world-guard.mjs fails any apply whose
-- applied world is not that file. A raster-derived column there would either break that guard
-- or push the roadstead into a JSON file where a hand edit could put it on land. A port's
-- coordinate is a fact about a CITY; the roadstead is a fact about the RASTER — and it is the
-- same measurement snap_nm already is, taken in the same pass by the same function, so it
-- belongs in the same row. Nullable for exactly as long as it takes to fill them, below.
alter table public.sea_reaches
  add column if not exists roadstead_lat numeric(6,3),
  add column if not exists roadstead_lon numeric(7,3);

comment on column public.sea_reaches.roadstead_lat is
  'THE ROADSTEAD (0076): the one point of open water this place is reached from. A course to '
  'this place BEGINS and ENDS here, and voyage.settle then docks her at the port itself. It is '
  'the cell voyage.water_roadstead answers for the quay coordinate, EXCEPT where the quay''s '
  'own cell is sailable water, in which case it IS the quay coordinate and snap_nm is 0 — so '
  'that gc(quay, roadstead) = snap_nm holds on every row and the helper line the chart draws '
  'is the distance the table measured. 3 dp is exact for a 0.25 degree raster.';

-- ── 2. THE FOLD: ONE BODY ANSWERS "WHERE IS THE WATER, AND HOW FAR" ────────────────────────────
-- voyage.water_snap_nm (0047:199) computed the winning cell at 0047:225-228 and threw the
-- coordinates away, so nothing in SQL could say WHERE a place is reached from. Its body moves
-- down here unchanged but for keeping the point, and water_snap_nm becomes one line over it.
-- NO SIGNATURE MOVES and no function is dropped: the three existing callers (0047:594, 0047:612,
-- and voyage.assert_paths_water) are untouched. This is what makes the headline cross-check
-- possible — the Node generator's column against the SQL rule, all 238 rows, below.
create or replace function voyage.water_roadstead(p_lat numeric, p_lon numeric)
returns table (nm numeric, lat numeric, lon numeric)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $wr$
declare
  r public.sea_raster%rowtype;
  v_row int; v_col int; ring int; dr int; dc int; rr int; cc int;
  v_best numeric := null;
  v_blat numeric; v_blon numeric;
  v_clat numeric; v_clon numeric;
  v_nm numeric;
begin
  select * into r from public.sea_raster where id = 1;
  v_row := least(r.rows - 1, greatest(0, floor((90 - p_lat) / r.cell_deg)::int));
  v_col := ((floor((p_lon + 180) / r.cell_deg)::int % r.cols) + r.cols) % r.cols;
  -- A POINT WHOSE OWN CELL IS SAILABLE WATER IS ITS OWN ROADSTEAD, at zero distance. Not the
  -- centre of that cell: the centre can lie up to 10.6 nm away, and a helper line whose length
  -- is not the measured snap is a picture of a number nothing computed (src/chart/route.ts:8-12).
  if get_bit(r.cells, (v_row * r.cols + v_col) * r.bits_per_cell) = 1 then
    nm := 0; lat := p_lat; lon := p_lon; return next; return;
  end if;
  for ring in 1 .. 12 loop
    for dr in -ring .. ring loop
      rr := v_row + dr;
      continue when rr < 0 or rr >= r.rows;
      for dc in -ring .. ring loop
        continue when greatest(abs(dr), abs(dc)) <> ring;
        cc := ((v_col + dc) % r.cols + r.cols) % r.cols;
        if get_bit(r.cells, (rr * r.cols + cc) * r.bits_per_cell) = 1 then
          v_clat := 90 - (rr + 0.5) * r.cell_deg;
          v_clon := -180 + (cc + 0.5) * r.cell_deg;
          v_nm := voyage.gc_distance_nm(p_lat::float8, p_lon::float8, v_clat::float8, v_clon::float8)::numeric;
          if v_best is null or v_nm < v_best then
            v_best := v_nm; v_blat := v_clat; v_blon := v_clon;
          end if;
        end if;
      end loop;
    end loop;
    exit when v_best is not null;
  end loop;
  -- 999 is 0047's own answer for "no water within 12 rings", kept so the fold changes no
  -- behaviour; there is no point to report with it, and the caller gets a null coordinate.
  nm := coalesce(v_best, 999); lat := v_blat; lon := v_blon; return next;
end $wr$;

revoke all on function voyage.water_roadstead(numeric, numeric) from public, anon, authenticated;

-- The same signature, the same answer, one line. Every existing caller is untouched, and there
-- is now exactly ONE body deciding where the nearest water is.
create or replace function voyage.water_snap_nm(p_lat numeric, p_lon numeric)
returns numeric
language sql
stable
security definer
set search_path = public, pg_temp
as $ws$
  select nm from voyage.water_roadstead(p_lat, p_lon)
$ws$;

revoke all on function voyage.water_snap_nm(numeric, numeric) from public, anon, authenticated;

-- ── The raster is NOT rewritten ────────────────────────────────────────────────────────────────
-- The grid this run built is byte-identical to the row public.sea_raster already holds
-- (545,989 water cells, 259200 packed bytes). Re-emitting 260 KB of the same base64 would
-- claim a change this file did not make. The self-assert still reads 13 named control cells
-- back through get_bit, because "unchanged" is a measurement too.

-- ── 3. THE ROADSTEADS AND THE SAILED DISTANCES BETWEEN THEM ────────────────────────────────────
-- Replaced whole rather than merged — the 0052:92-94 precedent, exactly. Every figure in the
-- table comes from ONE pass over ONE raster, and a half-updated table would be two authorities
-- for one distance. `reaches` is now measured ROADSTEAD to ROADSTEAD, because that is the
-- passage cmd.do_sail sells after this file: a table still quoting quay to quay would advertise
-- a passage the mover refuses, which is the very thing 0047:445-448 forbids.
delete from public.sea_reaches;

