  ) as v(code, snap_nm, rlat, rlon, reaches)
  join public.ports p on p.code = v.code;

-- Every row is filled, so the columns stop being optional. A NULL roadstead would mean a port
-- world.snapshot serves without one, and a client with no answer but to compute its own.
alter table public.sea_reaches
  alter column roadstead_lat set not null,
  alter column roadstead_lon set not null;

-- ── 4. THE MOVER ENDS THE COURSE AT THE ROADS ──────────────────────────────────────────────────
-- Four hunks, all inside THE ONE MOVER. cmd.divert needs none: it composes the onward passage
-- through cmd.issue -> cmd.do_sail, which is the whole point of there being one mover.
select pg_temp.recut('cmd.do_sail(uuid, jsonb)'::regprocedure, false,
  $o0$    select p.lat, p.lon into v_olat, v_olon from public.ports p where p.id = f.port_id;$o0$,
  $o1$    -- 0076 THE ROADSTEAD: she does not put to sea from the quay. Her course begins at the
    -- one point of open water this port is reached from — the same point the chart draws the
    -- dotted helper line to, served on world.snapshot().ports[].roadstead, so the line drawn,
    -- the course proposed and the endpoint verified are one answer and cannot drift.
    select sr.roadstead_lat, sr.roadstead_lon into v_olat, v_olon
      from public.sea_reaches sr where sr.port_id = f.port_id;$o1$,
  $h0$    v_head := coalesce((select snap_nm from public.sea_reaches where port_id = f.port_id), 0) + 25;$h0$,
  $h1$    -- 0076: a FLAT 25 nm, not the snap plus 25. The snap WAS the land-crossing exemption
    -- that let the straightener cut the coast; ending the course at the roads makes it
    -- unnecessary rather than merely smaller. 25 is not a new knob: it is the number already
    -- in this line, and the smallest one here that clears the 21.21 nm of sampling slack the
    -- client's own straightener spends at every path end (one cell diagonal,
    -- src/lib/sea/pathfind.ts:330), so a course the client passed cannot be refused for its
    -- own approach — the failure 0047:195-198 records finding the expensive way.
    v_head := 25;$h1$,
  $d0$    select p.lat, p.lon into v_dlat, v_dlon from public.ports p where p.id = v_dest;$d0$,
  $d1$    -- 0076 THE ROADSTEAD: she is bound for the roads, not the quay. Every port has a
    -- sea_reaches row (asserted in this file before anything relies on it), so a null here
    -- still means "no such port" and the refusal below is unchanged. voyage.settle then docks
    -- her at dest_port_id on the ETA exactly as it has since 0007 — which is the whole of the
    -- owner's "when the ship arrive at that point, consider it as the ship have landed".
    select sr.roadstead_lat, sr.roadstead_lon into v_dlat, v_dlon
      from public.sea_reaches sr where sr.port_id = v_dest;$d1$,
  $t0$    v_tail := coalesce((select snap_nm from public.sea_reaches where port_id = v_dest), 0) + 25;$t0$,
  $t1$    -- 0076: the flat 25 nm again, for the reason written on the head allowance above.
    v_tail := 25;$t1$);

-- ── 5. THE LAND GUARD TAKES THE SAME ALLOWANCE — AND GRANDFATHERS WHAT IT MUST ─────────────────
-- Without this hunk the guard would keep the hole this file just closed. With it and nothing
-- else, it would FAIL A PASSAGE A PLAYER LEGITIMATELY BOUGHT: voyages.path, total_nm and
-- speed_profile are frozen at departure (0047:453-500), so a fleet already at sea finishes the
-- voyage she paid for — over a course that began at her QUAY under the old allowance. The
-- column that says which rule she was admitted under already exists and is voyages.departed_at
-- (0006:63); the cutoff is the instant THIS FILE APPLIED, written in below. Legacy-converted
-- paths are still skipped and still counted, exactly as before.
-- An OPEN-WATER end keeps its MEASURED snap on either side of the cutoff, because cmd.do_sail
-- still grants it: a divert can lawfully cut a course inside a port's approach, and the guard
-- must judge by the rule the voyage was admitted under.
select pg_temp.recut('voyage.assert_paths_water()'::regprocedure, false,
  $g0$    v_head := coalesce((select sr.snap_nm from public.sea_reaches sr where sr.port_id = v.origin_port_id),
                       voyage.water_snap_nm((v_course->0->>0)::numeric, (v_course->0->>1)::numeric)) + 25;
    v_tail := coalesce((select sr.snap_nm from public.sea_reaches sr where sr.port_id = v.dest_port_id),
                       voyage.water_snap_nm((v_course->(jsonb_array_length(v_course)-1)->>0)::numeric,
                                            (v_course->(jsonb_array_length(v_course)-1)->>1)::numeric)) + 25;$g0$,
  format($g1$    -- 0076 THE ROADSTEAD. A course ORDERED FROM THIS INSTANT ON begins and ends at a
    -- roadstead, which is open water, so a port end gets the flat 25 nm of sampling slack and
    -- not the snap on top of it. A voyage ordered BEFORE it began at the quay and was admitted
    -- under snap + 25; judging her by a rule she was never sold would fail a passage a player
    -- legitimately bought (docs/DESIGN_ROADSTEAD.md 7). voyages.departed_at is the column that
    -- already answers which of the two she is.
    if v.origin_port_id is not null and v.departed_at >= %L::timestamptz then
      v_head := 25;
    else
      v_head := coalesce((select sr.snap_nm from public.sea_reaches sr where sr.port_id = v.origin_port_id),
                         voyage.water_snap_nm((v_course->0->>0)::numeric, (v_course->0->>1)::numeric)) + 25;
    end if;
    if v.dest_port_id is not null and v.departed_at >= %L::timestamptz then
      v_tail := 25;
    else
      v_tail := coalesce((select sr.snap_nm from public.sea_reaches sr where sr.port_id = v.dest_port_id),
                         voyage.water_snap_nm((v_course->(jsonb_array_length(v_course)-1)->>0)::numeric,
                                              (v_course->(jsonb_array_length(v_course)-1)->>1)::numeric)) + 25;
    end if;$g1$, v_cutoff, v_cutoff))
  from (select now()::text as v_cutoff) c;

-- ── 6. THE WIRE CARRIES IT ─────────────────────────────────────────────────────────────────────
-- world.snapshot() is the static world: ONE call, cached hard by the client (0009:19), already
-- the chart's only source of ports. world.reach(p_from) was measured and rejected as the home —
-- it is per-port, and the chart would need 238 calls to draw one layer. The correlated
-- subselect is the shape 0067 used for `buildings`, so the FROM clause does not move and the
-- slice is one hunk. Never null: every port has a sea_reaches row and this file asserts it
-- below, so there is no null arm for a client to reason about.
-- Deliberately NOT served: the raster row/col. The client already has the raster
-- (world.sea_raster); cell indices beside coordinates would be a second spelling of one fact.
select pg_temp.recut('world.snapshot()'::regprocedure, false,
  $w0$        'kind', p.kind, 'approach', p.approach,$w0$,
  $w1$        'kind', p.kind, 'approach', p.approach,
        'roadstead', (select jsonb_build_object(
                        'lat', sr.roadstead_lat, 'lon', sr.roadstead_lon, 'nm', sr.snap_nm)
                       from public.sea_reaches sr where sr.port_id = p.id),$w1$);

-- An assumed grant is how a read wall came down in 0018 and had to be rebuilt in 0023.
-- Re-issued explicitly for the one function a client calls, and asserted unmoved below.
revoke all on function world.snapshot() from public, anon;
grant execute on function world.snapshot() to authenticated;
revoke all on function cmd.do_sail(uuid, jsonb) from public, anon, authenticated;
revoke all on function voyage.assert_paths_water() from public, anon, authenticated;

-- ── SELF-ASSERT ────────────────────────────────────────────────────────────────────────────────
do $$
declare
  r          public.sea_raster%rowtype;
  c_probe    constant uuid := '00000000-0076-4000-8000-000000000001';
  -- The Lisbon -> Cadiz course this run's own pathfinder produced, ROADSTEAD to ROADSTEAD.
  c_course   constant jsonb := '[[38.625,-9.625],[36.875,-9.125],[36.625,-8.875],[36.375,-6.375]]'::jsonb;
  -- and the course the PROBE sails: LIS to SET, whose roadstead lies 26.17 nm off her
  -- quay — further than course_join_nm, which is what makes the destination hunk provable.
  c_probe_course constant jsonb := '[[38.625,-9.625],[38.125,-9.125]]'::jsonb;
  c_brs_ams  constant jsonb := '[[51.45,-2.6],[51.375,-4.625],[50.375,-5.625],[50.125,-5.875],[49.875,-5.625],[50.625,0.625],[52.875,4.375]]'::jsonb;
  v_n        int;
  v_bad      int;
  v_far      int;
  v_ports    int;
  v_missing  int;
  v_grants   int;
  v_nm       numeric;
  v_ref      text;
  v_isthmus  text;
  v_snap     numeric;
  v_road     jsonb;
  v_def      text;
  v_before   text;
  v_acl_b    text;
  v_acl_a    text;
  v_pan_lat  numeric; v_pan_lon numeric; v_pan_snap numeric; v_pan_rlat numeric; v_pan_rlon numeric;
  v_por_lat  numeric; v_por_lon numeric; v_por_snap numeric; v_por_rlat numeric; v_por_rlon numeric;
  v_city_line jsonb; v_road_line jsonb;
  v_player   uuid;
  v_fleet    uuid;
  v_res      jsonb;
  v_lat      numeric; v_lon numeric;
  v_eta      timestamptz;
  v_docked   uuid;
  v_status   text;
  v_walked   int;
begin
  -- (a) NOT VACUOUS: the table is populated, and EVERY port has a row. Every check below runs
  --     over these rows, and 0049:85 / 0065:4329 already assert this equality — it is asserted
  --     again HERE, before anything relies on it, because world.snapshot is about to serve a
  --     key that has no null arm.
  select count(*) into v_ports from public.ports;
  select count(*) into v_n from public.sea_reaches;
  if v_ports < 200 or v_n <> v_ports then
    raise exception '0076 self-assert FAIL: % reach row(s) for % port(s) — every check below would pass over nothing', v_n, v_ports;
  end if;
  select count(*) into v_missing from public.ports p
   where not exists (select 1 from public.sea_reaches sr where sr.port_id = p.id);
  if v_missing <> 0 then
    raise exception '0076 self-assert FAIL: % port(s) carry no sea_reaches row, so world.snapshot would serve them a null roadstead', v_missing;
  end if;

  -- (b) THE LINE DRAWN IS THE DISTANCE MEASURED. The chart draws the helper line from the quay
  --     to the roadstead and prints snap_nm beside it; if those are two numbers, the picture is
  --     about a quantity nothing computed (src/chart/route.ts:8-12). 0.01 nm is the rounding of
  --     snap_nm's own two decimal places, not a tolerance for error.
  select count(*) into v_bad
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   where abs(voyage.gc_distance_nm(p.lat::float8, p.lon::float8,
              sr.roadstead_lat::float8, sr.roadstead_lon::float8)::numeric - sr.snap_nm) > 0.01;
  if v_bad <> 0 then
    raise exception '0076 self-assert FAIL: % place(s) whose helper line is not snap_nm long — the line drawn would not be the distance measured', v_bad;
  end if;

  -- (c) A PORT ON ITS OWN WATER IS ITS OWN ROADSTEAD — and that is not the whole table.
  select count(*) into v_bad
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   where sr.snap_nm = 0 and (sr.roadstead_lat <> p.lat or sr.roadstead_lon <> p.lon);
  if v_bad <> 0 then
    raise exception '0076 self-assert FAIL: % place(s) snap 0 nm and yet hold a roadstead off the quay', v_bad;
  end if;
  select count(*) into v_far from public.sea_reaches where snap_nm > 0;
  if v_far < 100 then
    raise exception '0076 self-assert FAIL: only % place(s) hold a roadstead off the quay — 161 were measured, and a table of quay coordinates would pass (b) and (c) vacuously', v_far;
  end if;

  -- (d) EVERY ROADSTEAD STANDS ON SAILABLE WATER, asked of the raster itself rather than of the
  --     generator that wrote the column.
  select count(*) into v_bad from public.sea_reaches sr
   where voyage.water_snap_nm(sr.roadstead_lat, sr.roadstead_lon) <> 0;
  if v_bad <> 0 then
    raise exception '0076 self-assert FAIL: % roadstead(s) do not stand on sailable water', v_bad;
  end if;

  -- (e) THE GENERATOR AND THE SQL ARE ONE RULE. This is why water_snap_nm's body was folded
  --     down: a cross-implementation check over every row, not a re-read of what was written.
  select count(*) into v_bad
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) wr
   where wr.lat <> sr.roadstead_lat or wr.lon <> sr.roadstead_lon;
  if v_bad <> 0 then
    raise exception '0076 self-assert FAIL: % row(s) where the seeded roadstead POINT is not what voyage.water_roadstead answers — the Node generator and the SQL rule have drifted', v_bad;
  end if;
  -- and the DISTANCE, to the two decimal places snap_nm is stored at. The first draft of this
  -- check compared the two exactly and went red on all 161 off-quay rows on its own first
  -- apply: water_roadstead answers in full float precision and the column keeps two decimals.
  -- The tolerance is that rounding, not room for a disagreement.
  select count(*) into v_bad
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) wr
   where abs(wr.nm - sr.snap_nm) > 0.01;
  if v_bad <> 0 then
    raise exception '0076 self-assert FAIL: % row(s) where the seeded snap_nm is not what voyage.water_roadstead measures', v_bad;
  end if;

  -- (f) POSITIVE CONTROL #1 for (b): collapse ONE roadstead back onto its own quay — the exact
  --     regression this design fears — and require (b) to find it, EXACTLY ONCE. Rolled back.
  begin
    update public.sea_reaches sr
       set roadstead_lat = p.lat, roadstead_lon = p.lon
      from public.ports p
     where p.id = sr.port_id
       and sr.code = (select code from public.sea_reaches order by snap_nm desc, code limit 1);
    select count(*) into v_bad
      from public.sea_reaches sr join public.ports p on p.id = sr.port_id
     where abs(voyage.gc_distance_nm(p.lat::float8, p.lon::float8,
                sr.roadstead_lat::float8, sr.roadstead_lon::float8)::numeric - sr.snap_nm) > 0.01;
    if v_bad <> 1 then
      raise exception '0076 self-assert FAIL: a roadstead collapsed onto its own quay was found % time(s), expected exactly 1 — check (b) cannot bite and every green above it is vacuous', v_bad;
    end if;
    raise exception '__PROBE_ROLLBACK__' using errcode = 'P0001';
  exception when others then
    if sqlerrm <> '__PROBE_ROLLBACK__' then raise; end if;
  end;

  -- (g) THE HEADLINE, AND ITS OWN POSITIVE CONTROL — the isthmus of Panama.
  select p.lat, p.lon, sr.snap_nm, sr.roadstead_lat, sr.roadstead_lon
    into v_pan_lat, v_pan_lon, v_pan_snap, v_pan_rlat, v_pan_rlon
    from public.ports p join public.sea_reaches sr on sr.port_id = p.id where p.code = 'PAN';
  select p.lat, p.lon, sr.snap_nm, sr.roadstead_lat, sr.roadstead_lon
    into v_por_lat, v_por_lon, v_por_snap, v_por_rlat, v_por_rlon
    from public.ports p join public.sea_reaches sr on sr.port_id = p.id where p.code = 'POR';
  if v_pan_rlat is null or v_por_rlat is null then
    raise exception '0076 self-assert FAIL: PAN or POR carries no roadstead, so the headline proves nothing';
  end if;
  -- CONTROL, MUST STAY GREEN: the OLD quay-to-quay line is still ACCEPTED under the OLD
  -- allowance. If it ever stops being accepted, the defect this file claims to close was not
  -- there and the repair below proves nothing — so the file says so instead of shipping a boast.
  v_city_line := jsonb_build_array(jsonb_build_array(v_pan_lat, v_pan_lon),
                                   jsonb_build_array(v_por_lat, v_por_lon));
  if voyage.path_refusal(v_city_line, v_pan_lat, v_pan_lon, v_por_lat, v_por_lon,
                         public.wc_num('course_join_nm'),
                         v_pan_snap + 25, v_por_snap + 25) is not null then
    raise exception '0076 self-assert FAIL: the quay-to-quay isthmus line is ALREADY refused under the old allowance — the defect this file claims to close is not there';
  end if;
  -- THE REPAIR: the same passage between the two ROADSTEADS, under the flat allowance.
  v_road_line := jsonb_build_array(jsonb_build_array(v_pan_rlat, v_pan_rlon),
                                   jsonb_build_array(v_por_rlat, v_por_rlon));
  v_isthmus := voyage.path_refusal(v_road_line, v_pan_rlat, v_pan_rlon, v_por_rlat, v_por_rlon,
                                   public.wc_num('course_join_nm'), 25, 25);
  if v_isthmus is null or v_isthmus not like 'E_LAND%' then
    raise exception '0076 self-assert FAIL: the line from the Panama City roads to the Port Royal roads is not refused as E_LAND (got %) — the isthmus is open and the short way across it is still purchasable', coalesce(v_isthmus, 'ACCEPTED');
  end if;
  -- and the table agrees with the law: the reach is the long way round now.
  v_nm := (select (reaches->>'POR')::numeric from public.sea_reaches where code = 'PAN');
  if v_nm is null or v_nm < 5000 then
    raise exception '0076 self-assert FAIL: PAN->POR is served at % nm — the quay would advertise a passage the mover refuses', v_nm;
  end if;

  -- (h) THE WIRE CARRIES IT, FOR EVERY PORT.
  select count(*) into v_bad
    from jsonb_array_elements(world.snapshot()->'ports') p
   where p->'roadstead' is null or p->'roadstead'->>'lat' is null
      or p->'roadstead'->>'lon' is null or p->'roadstead'->>'nm'  is null;
  if v_bad <> 0 then
    raise exception '0076 self-assert FAIL: % served port(s) carry no roadstead — a client would have to compute one', v_bad;
  end if;
  select p->'roadstead' into v_road from jsonb_array_elements(world.snapshot()->'ports') p
   where p->>'code' = 'AMS';
  if (v_road->>'nm')::numeric <= 20 then
    raise exception '0076 self-assert FAIL: Amsterdam is served a roadstead % nm off the quay — 35.47 was measured, and a table of zeroes serves fine and draws nothing', v_road->>'nm';
  end if;
  if (v_road->>'lat')::numeric <> (select roadstead_lat from public.sea_reaches where code = 'AMS') then
    raise exception '0076 self-assert FAIL: the served roadstead is not the stored one';
  end if;
  -- NOTHING ELSE MOVED on the wire: the re-cut body is its own pre-image with exactly this hunk
  -- swapped in, and the grants are the ones it had.
  select def, acl into v_before, v_acl_b from defs_before_0076 where fn = 'world.snapshot()';
  v_def := pg_get_functiondef('world.snapshot()'::regprocedure);
  select p.proacl::text into v_acl_a from pg_proc p where p.oid = 'world.snapshot()'::regprocedure;
  if position('roadstead' in v_before) <> 0 then
    raise exception '0076 self-assert FAIL: the pre-image already served a roadstead — this slice is a no-op';
  end if;
  if replace(v_def,
       $x$        'kind', p.kind, 'approach', p.approach,
        'roadstead', (select jsonb_build_object(
                        'lat', sr.roadstead_lat, 'lon', sr.roadstead_lon, 'nm', sr.snap_nm)
                       from public.sea_reaches sr where sr.port_id = p.id),$x$,
       $y$        'kind', p.kind, 'approach', p.approach,$y$) <> v_before then
    raise exception '0076 self-assert FAIL: world.snapshot is not its own pre-image with exactly the declared hunk swapped in';
  end if;
  if v_acl_a is distinct from v_acl_b then
    raise exception '0076 self-assert FAIL: world.snapshot grants moved (% -> %)', v_acl_b, v_acl_a;
  end if;

  -- (i) A REAL HOUSE SAILS, AND HER COURSE STARTS AT THE ROADS — then she docks AT THE PORT.
  --     The 0075/0063 probe shape, rolled back. This is the owner's sentence PROVEN rather than
  --     argued, with voyage.settle untouched.
  begin
    v_player := public.new_house(c_probe, 'Casa das Roadas', 'PRT');
    perform cmd.assume_identity(c_probe);
    select id into v_fleet from public.fleets where player_id = v_player;
    -- Pinned for the reason 0037, 0063 and 0075 pin it: a hazard drawn on this passage would
    -- delay her and this probe would be measuring the dice rather than the geometry.
    update public.world_config set value = to_jsonb(0.0) where key = 'hazard_p_max';
    perform cmd.do_provision(v_fleet, jsonb_build_object('mode', 'FULL'));
    -- A REFUSAL IS AN ENVELOPE, NOT AN EXCEPTION (0008).
    v_res := cmd.issue(v_fleet, 'SAIL TO SET', null, c_probe_course);
    if coalesce(v_res->>'ok', 'false') <> 'true' then
      raise exception '0076 self-assert FAIL: the probe could not put to sea on a roadstead-to-roadstead course: [%: %]',
        v_res->>'error_code', v_res->>'error_message';
    end if;
    perform cmd.advance(v_fleet);
    select (path->0->'a'->>0)::numeric, (path->0->'a'->>1)::numeric, eta
      into v_lat, v_lon, v_eta
      from public.voyages where fleet_id = v_fleet and status = 'SAILING';
    if v_lat is null then
      raise exception '0076 self-assert FAIL: the probe never put a voyage to sea, so this proves nothing';
    end if;
    if v_lat is distinct from (select roadstead_lat from public.sea_reaches where code = 'LIS')
       or v_lon is distinct from (select roadstead_lon from public.sea_reaches where code = 'LIS') then
      raise exception '0076 self-assert FAIL: her course begins at (%, %) and not at Lisbon''s roadstead (%, %) — the mover still departs from the quay',
        v_lat, v_lon,
        (select roadstead_lat from public.sea_reaches where code = 'LIS'),
        (select roadstead_lon from public.sea_reaches where code = 'LIS');
    end if;
    select (path->(jsonb_array_length(path)-1)->'b'->>0)::numeric into v_lat
      from public.voyages where fleet_id = v_fleet and status = 'SAILING';
    if v_lat is distinct from (select roadstead_lat from public.sea_reaches where code = 'SET') then
      raise exception '0076 self-assert FAIL: her course ends at % and not at Setubal''s roadstead', v_lat;
    end if;
    select total_nm into v_nm from public.voyages where fleet_id = v_fleet and status = 'SAILING';
    if v_nm is null or v_nm <= 0 then
      raise exception '0076 self-assert FAIL: a course of % nm', v_nm;
    end if;
    -- THE OWNER'S SENTENCE. She reaches the point, and voyage.settle — untouched by this file —
    -- docks her AT THE PORT.
    perform voyage.settle(v_fleet, v_eta + interval '1 second');
    select port_id, status into v_docked, v_status from public.fleets where id = v_fleet;
    if v_status <> 'DOCKED' or v_docked is distinct from (select id from public.ports where code = 'SET') then
      raise exception '0076 self-assert FAIL: she reached the Setubal roads and is [%] at [%] — arriving at the roadstead must dock her at the port itself',
        v_status, coalesce((select code from public.ports where id = v_docked), 'nowhere');
    end if;
    -- AND THE GUARD WALKS HER. Non-vacuity is the caller's duty (the guard's own header).
    select voyages_walked into v_walked from voyage.assert_paths_water();
    if v_walked < 1 then
      raise exception '0076 self-assert FAIL: the land guard walked % course(s) — it is asserting over nothing', v_walked;
    end if;
    -- POSITIVE CONTROL #2 FOR THE GRANDFATHER CLAUSE, both directions on ONE planted voyage:
    -- the quay-to-quay isthmus passage, which is legal under the OLD allowance and land under
    -- the NEW one. Dated BEFORE this migration it must be walked and accepted; dated after, the
    -- same row must be refused as land.
    insert into public.voyages (fleet_id, player_id, path, total_nm, speed_profile,
                                departed_at, eta, status, last_settled_day, origin_port_id, dest_port_id)
    select v_fleet, v_player, s.segs,
           (select sum((x->>'nm')::numeric) from jsonb_array_elements(s.segs) x),
           '[4.5]'::jsonb, timestamptz '2000-01-01', timestamptz '2000-01-02',
           'ARRIVED', 1,
           (select id from public.ports where code = 'PAN'),
           (select id from public.ports where code = 'POR')
      from (select voyage.segments_from_course(v_city_line) as segs) s;
    select voyages_walked into v_walked from voyage.assert_paths_water();
    if v_walked < 2 then
      raise exception '0076 self-assert FAIL: the grandfathered isthmus voyage was not walked (% course(s)) — the guard skipped it rather than accepting it', v_walked;
    end if;
    update public.voyages set departed_at = now(), eta = now() + interval '1 hour'
     where fleet_id = v_fleet and status = 'ARRIVED' and dest_port_id = (select id from public.ports where code = 'POR');
    begin
      perform * from voyage.assert_paths_water();
      raise exception '0076 self-assert FAIL: the SAME isthmus course dated after this migration was still accepted — the guard kept the hole this file closed';
    exception when others then
      if sqlerrm like '0076 self-assert FAIL%' then raise; end if;
      if position('E_LAND' in sqlerrm) = 0 then
        raise exception '0076 self-assert FAIL: the guard refused the post-cutoff isthmus voyage for the wrong reason: %', sqlerrm;
      end if;
    end;
    raise exception '__PROBE_ROLLBACK__' using errcode = 'P0001';
  exception when others then
    if sqlerrm <> '__PROBE_ROLLBACK__' then raise; end if;
  end;

  -- (j) POSTURE. Both halves, per README §3: a TABLE write grant and an EXECUTE on a
  --     SECURITY DEFINER writer are two different doors, and 0018 exists because the first read
  --     an honest zero for seventeen migrations while the second was open.
  select count(*) into v_grants from public.client_write_grants();
  if v_grants <> 0 then raise exception '0076 self-assert FAIL: % client write grant(s)', v_grants; end if;
  select count(*) into v_grants from public.client_executable_writers();
  if v_grants <> 0 then raise exception '0076 self-assert FAIL: % client-executable writer(s)', v_grants; end if;
  if not has_table_privilege('authenticated', 'public.sea_reaches', 'select')
     or has_function_privilege('anon', 'voyage.water_roadstead(numeric, numeric)', 'execute')
     or has_function_privilege('authenticated', 'voyage.water_roadstead(numeric, numeric)', 'execute')
     or has_function_privilege('authenticated', 'voyage.water_snap_nm(numeric, numeric)', 'execute')
     or has_function_privilege('anon', 'world.snapshot()', 'execute')
     or not has_function_privilege('authenticated', 'world.snapshot()', 'execute') then
    raise exception '0076 self-assert FAIL: the grant posture is wrong — the roadstead rule is server-only and the snapshot is the client''s';
  end if;

  -- ── AND THE TABLE'S OWN PROPERTIES, because this file rewrote every row of it ────────────────
  -- (k) THE RASTER IS THERE AND THE BIT ORDER IS THE ONE THE CLIENT PACKS. 13 control cells,
  --     each a named piece of the world, read through get_bit — the same read the sampler uses.
  select * into r from public.sea_raster where id = 1;
  if r.cols <> 1440 or r.rows <> 720 or r.bits_per_cell <> 2 or octet_length(r.cells) <> 259200 then
    raise exception '0076 self-assert FAIL: the raster is % x % at % bit(s) with % bytes — expected 1440 x 720 at 2 with 259200', r.cols, r.rows, r.bits_per_cell, octet_length(r.cells);
  end if;
  if get_bit(r.cells, 692320) <> 1 then
    raise exception '0076 self-assert FAIL: the mid-Atlantic (30, -40) reads %, expected 1', get_bit(r.cells, 692320);
  end if;
  if get_bit(r.cells, 583164) <> 0 then
    raise exception '0076 self-assert FAIL: the middle of Iberia (39.5, -4.5) reads %, expected 0', get_bit(r.cells, 583164);
  end if;
  if get_bit(r.cells, 566152) <> 1 then
    raise exception '0076 self-assert FAIL: the Bosphorus channel (41, 29) reads %, expected 1', get_bit(r.cells, 566152);
  end if;
  if get_bit(r.cells, 175200) <> 0 then
    raise exception '0076 self-assert FAIL: the Siberian arctic (ice) (75, 120) reads %, expected 0', get_bit(r.cells, 175200);
  end if;
  if get_bit(r.cells, 232160) <> 1 then
    raise exception '0076 self-assert FAIL: the Barents Sea (open — the Muscovy road) (70, 40) reads %, expected 1', get_bit(r.cells, 232160);
  end if;
  if get_bit(r.cells, 1787040) <> 0 then
    raise exception '0076 self-assert FAIL: the Antarctic pack (-65, 0) reads %, expected 0', get_bit(r.cells, 1787040);
  end if;
  if get_bit(r.cells, 900896) <> 1 then
    raise exception '0076 self-assert FAIL: the South China Sea (12, 112) reads %, expected 1', get_bit(r.cells, 900896);
  end if;
  if get_bit(r.cells, 773360) <> 0 then
    raise exception '0076 self-assert FAIL: the Sahara (23, 10) reads %, expected 0', get_bit(r.cells, 773360);
  end if;
  if get_bit(r.cells, 444934) <> 1 then
    raise exception '0076 self-assert FAIL: the Bristol Channel off Barry (51.4, -3.1) reads %, expected 1', get_bit(r.cells, 444934);
  end if;
  if get_bit(r.cells, 444938) <> 1 then
    raise exception '0076 self-assert FAIL: the Severn approach at Bristol (51.45, -2.6) reads %, expected 1', get_bit(r.cells, 444938);
  end if;
  if get_bit(r.cells, 439172) <> 0 then
    raise exception '0076 self-assert FAIL: the Welsh hills above the channel (52, -3.5) reads %, expected 0', get_bit(r.cells, 439172);
  end if;
  if get_bit(r.cells, 1717920) <> 1 then
    raise exception '0076 self-assert FAIL: the Southern Ocean at 59°S (open) (-59, 0) reads %, expected 1', get_bit(r.cells, 1717920);
  end if;
  if get_bit(r.cells, 1740960) <> 0 then
    raise exception '0076 self-assert FAIL: the pack at 61°S (closed) (-61, 0) reads %, expected 0', get_bit(r.cells, 1740960);
  end if;

  -- (l) EVERY PLACE REACHES EVERY OTHER PLACE, symmetrically. Non-vacuous by the counts
  --     themselves: the world cannot hold an island nobody can sail to.
  select count(*) into v_bad from public.sea_reaches sr
   where (select count(*) from jsonb_object_keys(sr.reaches)) <> v_ports - 1;
  if v_bad <> 0 then
    raise exception '0076 self-assert FAIL: % place(s) do not reach every other place', v_bad;
  end if;
  select count(*) into v_bad
    from public.sea_reaches a
   cross join lateral jsonb_each_text(a.reaches) e(code, nm)
    join public.sea_reaches b on b.code = e.code
   where (b.reaches->>a.code)::numeric is distinct from e.nm::numeric;
  if v_bad <> 0 then
    raise exception '0076 self-assert FAIL: % asymmetric pair reading(s)', v_bad;
  end if;

  -- (m) NO SAILED DISTANCE IS SHORTER THAN THE GREAT CIRCLE — and after this file the great
  --     circle it must clear is the one BETWEEN THE ROADSTEADS, because that is what was sailed.
  --     Comparing against the quay-to-quay line would be comparing two different passages.
  select count(*) into v_bad
    from public.sea_reaches a
   cross join lateral jsonb_each_text(a.reaches) e(code, nm)
    join public.sea_reaches b on b.code = e.code
   where a.code < e.code
     and e.nm::numeric < voyage.gc_distance_nm(a.roadstead_lat::float8, a.roadstead_lon::float8,
                                               b.roadstead_lat::float8, b.roadstead_lon::float8) * 0.995;
  if v_bad <> 0 then
    raise exception '0076 self-assert FAIL: % pair(s) sail shorter than the great circle between their roadsteads', v_bad;
  end if;

  -- (n) THE WORLD'S THREE STANDING FACTS, unmoved by the reshape: no Arctic road, no Suez, no
  --     Panama. If ending courses at the roads had quietly opened one of them, this bites.
  v_nm := (select (reaches->>'NAG')::numeric from public.sea_reaches where code = 'LIS');
  if v_nm is null or v_nm < 12000 then
    raise exception '0076 self-assert FAIL: LIS->NAG is % nm — under 12,000 means the Arctic is open again (the leg graph served 7,565 over the pole)', v_nm;
  end if;
  if (select (reaches->>'ADE')::numeric from public.sea_reaches where code = 'ALE') < 9000 then
    raise exception '0076 self-assert FAIL: ALE->ADE under 9,000 nm — a Suez Canal three centuries early';
  end if;
  if (select (reaches->>'ACA')::numeric from public.sea_reaches where code = 'VER') < 9000 then
    raise exception '0076 self-assert FAIL: VER->ACA under 9,000 nm — a Panama Canal three centuries early';
  end if;
  select snap_nm into v_snap from public.sea_reaches where code = 'BRS';
  if v_snap is null or v_snap > 20 then
    raise exception '0076 self-assert FAIL: Bristol snaps % nm to sailable water — over 20 means the Severn is land again (it was 64.55 nm to Lyme Bay)', v_snap;
  end if;

  -- (o) THE MEASURE AND THE LAW, on two real courses this run's own pathfinder produced between
  --     the very roadsteads the table now holds — accepted under the FLAT allowance, which is
  --     the allowance the re-cut mover grants. A course that needed more would mean the
  --     roadstead did not remove the need for the snap exemption.
  v_ref := voyage.path_refusal(c_course,
             (select roadstead_lat from public.sea_reaches where code = 'LIS'),
             (select roadstead_lon from public.sea_reaches where code = 'LIS'),
             (select roadstead_lat from public.sea_reaches where code = 'CAD'),
             (select roadstead_lon from public.sea_reaches where code = 'CAD'),
             public.wc_num('course_join_nm'), 25, 25);
  if v_ref is not null then
    raise exception '0076 self-assert FAIL: the real Lisbon->Cadiz roads-to-roads course was refused under the flat 25 nm allowance: %', v_ref;
  end if;
  v_ref := voyage.path_refusal(c_brs_ams,
             (select roadstead_lat from public.sea_reaches where code = 'BRS'),
             (select roadstead_lon from public.sea_reaches where code = 'BRS'),
             (select roadstead_lat from public.sea_reaches where code = 'AMS'),
             (select roadstead_lon from public.sea_reaches where code = 'AMS'),
             public.wc_num('course_join_nm'), 25, 25);
  if v_ref is not null then
    raise exception '0076 self-assert FAIL: the real Bristol->Amsterdam roads-to-roads course was refused under the flat 25 nm allowance: %', v_ref;
  end if;
  -- the negative control the sampler has carried since 0046: a straight line across Iberia.
  v_ref := voyage.path_refusal(
             jsonb_build_array(jsonb_build_array(38.71, -9.14), jsonb_build_array(41.38, 2.18)),
             38.71, -9.14, 41.38, 2.18, 15, 40, 40);
  if v_ref is null or v_ref not like 'E_LAND:%' then
    raise exception '0076 self-assert FAIL: a straight Lisbon->Barcelona line across Iberia was NOT refused as land (got [%])', coalesce(v_ref, 'null');
  end if;

  raise notice '0076 self-assert ok: A HARBOUR IS REACHED FROM ITS ROADS. % places carry a roadstead; 161 of them lie off the quay (worst LNG 67.68 nm, AMS 35.47 nm) and 77 stand on their own water at 0 nm and ARE their own roadstead. Every one of them is on sailable water, every one is exactly snap_nm from its quay so the helper line the chart draws is the distance the table measured, and every one equals what voyage.water_roadstead answers for the same coordinate — the Node generator and the SQL rule are one rule now, because water_snap_nm''s body moved down into it. Collapsing one roadstead onto its quay is FOUND, exactly once. The isthmus: PAN to POR quay-to-quay is still ACCEPTED under the old snap+25 allowance (so the defect was real) and roads-to-roads is refused %, with the table now quoting % nm the long way round. A real house sailed LIS to SET — whose roadstead lies 26.17 nm off her quay, further than the join tolerance, so nothing here would work from the quay — on a roadstead-to-roadstead course; her frozen path BEGAN at the LIS roads, ENDED at the SET roads, and voyage.settle — untouched — docked her at SET itself: the owner''s sentence, proven. The land guard walks her, GRANDFATHERS a pre-0076 isthmus voyage a player would already have bought, and refuses the same course dated after this file. Every place still reaches every other symmetrically and never under the great circle between their roadsteads; the Arctic is shut (LIS->NAG % nm), there is no Suez and no Panama; 13 raster control cells read back through get_bit; 0 client write grants, 0 client-executable writers.',
    v_ports, v_isthmus, (select (reaches->>'POR')::numeric from public.sea_reaches where code = 'PAN'),
    (select (reaches->>'NAG')::numeric from public.sea_reaches where code = 'LIS');
end $$;
